const st = await tools.mcp__gui__get_window_state({pid:171419, window_id:23108591, include_screenshot:false, tree_format:"elements", max_elements:120});
const sc = st.structuredContent;
const sid = sc.snapshot_id;
const els = sc.elements || [];
const desk = els.find(e => e.label === "Desktop" && e.role === "table cell");
if(!desk) return "no desktop cell";
let r = await tools.mcp__gui__click({element_token: `${sid}:${desk.element_index ?? desk.index}`, count:2});
return r.isError ? r.content : "activated Desktop";

